// reportFeatures.spec.js
import { REPORT_CATALOG } from '@/config/reportFeatures'

describe('REPORT_CATALOG', () => {
  it('id 与 routePath 唯一', () => {
    const ids = REPORT_CATALOG.map((i) => i.id)
    const paths = REPORT_CATALOG.map((i) => i.routePath)
    expect(new Set(ids).size).toBe(ids.length)
    expect(new Set(paths).size).toBe(paths.length)
  })

  it('已下线的员工工时报表不应存在', () => {
    expect(REPORT_CATALOG.some((i) => i.id === 'employee-hours')).toBe(false)
  })
})
